const API='http://127.0.0.1:8000'; let data=null,drawerOpen=false,uploadResult=null,showDetails=false,scenarioState={energy:-8,fuel:-4,production:6,result:null},optimizationState={budget:45,target:5,downtime:7,result:null};
const pages=[['dashboard','Home','START'],['data-center','Upload Data','START'],['sustainability','Find Pollution','UNDERSTAND'],['scenario-lab','Try Changes','UNDERSTAND'],['interventions','Choose Solutions','TAKE ACTION'],['optimization','Best Plan','TAKE ACTION'],['decision-contracts','Set Success Rules','TAKE ACTION'],['verification','Check Results','CHECK & LEARN'],['decision-memory','Past Results','CHECK & LEARN'],['insights','Next Steps','CHECK & LEARN']];
const pageInfo={
 dashboard:{step:'Start here',title:'See the big picture',text:'Know how much pollution the company creates, whether the data is trustworthy, and what needs attention first.',example:'Example: Chennai air-conditioning is the biggest electricity problem.',next:'data-center',nextLabel:'Upload your data'},
 'data-center':{step:'Step 1',title:'Upload monthly usage data',text:'Add a simple CSV file containing electricity, fuel, water, or waste readings.',example:'Example: Chennai used 985,400 kWh of electricity in August.',next:'sustainability',nextLabel:'Find the biggest problem'},
 sustainability:{step:'Step 2',title:'Find where pollution comes from',text:'See which factory activity creates the most carbon pollution.',example:'Example: Chennai air-conditioning creates 28.7% of reported emissions.',next:'scenario-lab',nextLabel:'Try a possible change'},
 'scenario-lab':{step:'Step 3',title:'Try an idea before spending money',text:'Move three sliders to see what may happen if energy, fuel, or production changes.',example:'Example: Reduce electricity by 8% while production grows by 6%.',next:'interventions',nextLabel:'See possible solutions'},
 interventions:{step:'Step 4',title:'Compare possible solutions',text:'Compare solar, efficient machines, air-conditioning improvements, and electric vehicles.',example:'Example: HVAC improvement costs ₹2.4 lakh and may save 164 tonnes of carbon.',next:'optimization',nextLabel:'Choose the best plan'},
 optimization:{step:'Step 5',title:'Find the best plan for your budget',text:'Enter your available money, carbon goal, and maximum shutdown days.',example:'Example: With ₹45 lakh and 7 days, choose the highest-saving combination.',next:'decision-contracts',nextLabel:'Set success rules'},
 'decision-contracts':{step:'Step 6',title:'Write down what success means',text:'Set the expected saving, minimum acceptable saving, and checking period before work starts.',example:'Example: The project succeeds only if electricity per product falls by at least 8%.',next:'verification',nextLabel:'Check the result'},
 verification:{step:'Step 7',title:'Check whether the project worked',text:'Compare what was expected with what actually happened.',example:'Example: Expected 14% saving; measured saving was 10.3%.',next:'decision-memory',nextLabel:'Save what you learned'},
 'decision-memory':{step:'Step 8',title:'Learn from past projects',text:'Remember which predictions were right or wrong so the next estimate is more realistic.',example:'Example: Future HVAC estimates are reduced because earlier estimates were too high.',next:'insights',nextLabel:'See recommended next steps'},
 insights:{step:'Finish',title:'See clear next actions',text:'Get a short list of recommended actions based on the uploaded data and verified results.',example:'Example: Extend the Chennai test for 14 more days.',next:'dashboard',nextLabel:'Return home'}
};
const icon={dashboard:'◫','data-center':'▦',sustainability:'⌁','scenario-lab':'⌘',interventions:'◇',optimization:'◎','decision-contracts':'▣',verification:'✓','decision-memory':'▤',insights:'✦'};
function metric(label,value,note){return `<div class="metric"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`}
function badge(label,warn=false){return `<span class="badge ${warn?'warn':''}">${label}</span>`}
function head(k,t,d,a=''){return `<div class="head"><div><div class="kicker">${k}</div><h2>${t}</h2><p>${d}</p></div><div class="actions">${a}</div></div>`}
function pageGuide(page){const p=pageInfo[page]||pageInfo.dashboard,top=data.has_data&&data.hotspots[0],live=data.has_data?{dashboard:`Your ${data.analysis.rows} uploaded rows produced ${data.overview.co2e_t.toLocaleString()} tonnes of carbon pollution.`,'data-center':`${data.analysis.rows} unique rows are active with a ${data.data_quality.overall}% quality score.`,sustainability:`${top?.resource||'The largest source'} at ${top?.facility||'your facility'} is currently the biggest source.`,'scenario-lab':`Your uploaded starting point is ${data.overview.co2e_t.toLocaleString()} tonnes CO₂e.`,interventions:`Solution benefits are scaled to the pollution found in your CSV.`,optimization:`The planner now uses ${data.overview.co2e_t.toLocaleString()} tonnes as the reduction baseline.`,'decision-contracts':`The baseline period is ${data.organization.period}.`,verification:`The latest uploaded month changed ${signed(data.overview.co2e_change)}% from the previous month.`,'decision-memory':`The current learning factor is ${data.calibration.factor}.`,insights:`The first recommendation focuses on ${top?.resource?.toLowerCase()||'your largest source'}.`}[page]:p.example;return `<section class="plain-guide"><div><span>${p.step}</span><h2>${p.title}</h2><p>${p.text}</p><small>💡 ${live}</small></div><button class="btn primary" onclick="go('${p.next}')">${p.nextLabel} →</button></section>`}
function shell(page,body){let last='';const nav=pages.map(([id,label,group],index)=>{const g=group!==last?`<div class="navlabel">${last=group}</div>`:'';return `${g}<a class="nav ${page===id?'active':''}" href="/${id}" onclick="event.preventDefault();go('${id}')"><span>${index+1}</span>${label}</a>`}).join('');const status=data.has_data?`<span class="data-status ready"><i></i>${data.analysis.rows} rows ready</span>`:`<span class="data-status"><i></i>No data uploaded</span>`,clear=data.has_data?`<button class="clear-data" onclick="clearData()">Clear data</button>`:'';return `<div class="shell ${showDetails?'show-details':'simple-view'}"><aside class="side"><div class="brand"><div class="mark">◒</div>EcoMind <small>Simple</small></div><div class="org"><div class="avatar">AC</div><div><b>Aster Components</b><small>Your sustainability guide</small></div></div>${nav}<footer>Start at Upload Data.<br>Your CSV controls every result.</footer></aside><main class="main"><header class="top"><div><small>${data.organization.name}</small><h1>${pages.find(p=>p[0]===page)?.[1]||'Home'}</h1></div><div class="top-actions">${status}${clear}<button class="details-toggle" onclick="toggleDetails()">${showDetails?'Use simple view':'Show detailed data'}</button></div></header><div class="page page-${page}">${pageGuide(page)}${body}</div></main></div>`}
function overview(){const o=data.overview,bars=o.trend.map((v,i)=>`<div class="bar" style="height:${v/8}%" data-label="${['Sep','Oct','Nov','Dec','Jan','Feb','Mar','Apr','May','Jun','Jul','Aug'][i]}"></div>`).join('');return head(`REPORTING PERIOD · ${data.organization.period}`,'From footprint to proof','See where environmental impact sits, what is being tested, and which improvements have survived verification.',`<button class="btn" onclick="go('hotspots')">Review hotspots</button><button class="btn primary" onclick="go('interventions')">Open action →</button>`)+`<div class="metrics">${metric('Total emissions','6,428 tCO₂e','−6.4% vs prior period')}${metric('Energy','11,820 MWh','−3.8% intensity')}${metric('Water','47.2 ML','−2.1% intensity')}${metric('Waste','284 t','+1.4% absolute')}${metric('Data readiness','86 / 100','EcoMind heuristic')}${metric('Verified impact','241 tCO₂e','3 verified actions')}</div><div class="grid"><section class="panel c8"><div class="ph"><div><h3>Environmental trend</h3><span class="sub">Monthly tCO₂e · all facilities</span></div>${badge('On track')}</div><div class="chart">${bars}</div></section><section class="panel c4"><div class="ph"><div><h3>Top hotspot</h3><span class="sub">28.7% of footprint</span></div><b>#1</b></div><div class="focus"><span>Chennai HVAC electricity</span><div class="big">1,842 <small>tCO₂e</small></div><div class="progress"><i style="width:72%"></i></div><p>Energy intensity is 4.2% above the comparable production baseline.</p><button class="btn primary" onclick="go('interventions')">Review intervention →</button></div></section><section class="panel c7"><div class="ph"><div><h3>ProofLoop in motion</h3><span class="sub">Interventions by lifecycle</span></div></div><div class="flow"><div class="node">5<br><b>Hypotheses</b></div><span class="arrow">→</span><div class="node">2<br><b>Pilot ready</b></div><span class="arrow">→</span><div class="node warn">2<br><b>Running</b></div><span class="arrow">→</span><div class="node good">3<br><b>Verified</b></div></div></section><section class="panel c5"><div class="ph"><div><h3>Recent decision memory</h3><span class="sub">Evidence-backed events</span></div></div><div class="events">${data.audit.map(e=>`<div class="event"><i></i><div><b>${e.event}</b><br><small>${e.detail}</small></div><small>${e.time}</small></div>`).join('')}</div></section></div>`}
function dashboard(){const o=data.overview,spent=data.interventions.filter(i=>['Pilot ready','Verified','Candidate'].includes(i.status)).slice(0,3).reduce((sum,i)=>sum+i.cost_lakh,0),allocated=50;const months=['Sep','Oct','Nov','Dec','Jan','Feb','Mar','Apr','May','Jun','Jul','Aug'];const stacked=o.trend.map((total,i)=>{const electric=Math.round(total*.68),fuel=Math.round(total*.19),water=Math.round(total*.07),waste=total-electric-fuel-water;return `<div class="stackcol"><div class="stackbar" title="${months[i]} · ${total} tCO₂e"><i class="electric" style="height:${electric/8}%"></i><i class="fuel" style="height:${fuel/8}%"></i><i class="water" style="height:${water/8}%"></i><i class="waste" style="height:${waste/8}%"></i></div><small>${months[i]}</small></div>`}).join('');const work=data.interventions.slice(0,4),progress=[72,61,100,18];return head('SUSTAINABILITY COMMAND CENTER','Executive control plane','Monitor emissions, capital deployment, evidence quality, and intervention execution from one decision-ready surface.',`<button class="btn" onclick="go('data-center')">Review data quality</button><button class="btn primary" onclick="go('verification')">Open verification →</button>`)+`<div class="exec-strip"><article class="exec-card"><div><span>NET EMISSIONS</span><b class="delta good">↓ ${Math.abs(o.co2e_change)}%</b></div><strong>${o.co2e_t.toLocaleString()} <small>tCO₂e</small></strong><div class="scope-row"><em>S1 · 24%</em><em>S2 · 58%</em><em>S3 · 18%</em></div></article><article class="exec-card"><div><span>BUDGET UTILIZED</span><b>${Math.round(spent/allocated*100)}%</b></div><strong>₹${spent.toFixed(1)}L <small>of ₹${allocated}L</small></strong><div class="progress budget"><i style="width:${spent/allocated*100}%"></i></div><p>${work.length} funded initiatives across 3 facilities</p></article><article class="exec-card"><div><span>DATA QUALITY INDEX</span>${badge('Decision-ready')}</div><strong>${o.data_readiness}% <small>validated</small></strong><div class="quality-dots"><i></i><i></i><i></i><i class="muted"></i></div><p>Electricity and fuel streams lead coverage</p></article><article class="exec-card"><div><span>ACTIVE INTERVENTIONS</span><b class="live-dot">LIVE</b></div><strong>${o.active_pilots} <small>ongoing pilots</small></strong><p><b class="good">3 verified</b> · 2 pilot-ready · 5 hypotheses</p></article></div><div class="grid"><section class="panel c8"><div class="ph"><div><h3>Emissions & operating drivers</h3><span class="sub">Monthly contribution · Electricity, Fuel, Water, Waste</span></div><div class="legend compact"><span><i class="electric"></i>Electricity</span><span><i class="fuel"></i>Fuel</span><span><i class="water"></i>Water</span><span><i class="waste"></i>Waste</span></div></div><div class="stackchart">${stacked}</div></section><section class="panel c4"><div class="ph"><div><h3>Organizational hotspots</h3><span class="sub">Contribution to reported footprint</span></div><button class="mini-link" onclick="go('sustainability')">Deep dive →</button></div><div class="hotspot-list">${data.hotspots.map((h,i)=>`<div><span><b>0${i+1}</b>${h.resource}<small>${h.facility}</small></span><strong>${h.contribution}%</strong><i><em style="width:${h.contribution*3}%"></em></i></div>`).join('')}</div></section><section class="panel c12"><div class="ph"><div><h3>Budget & financial efficiency</h3><span class="sub">Funded intervention execution, return profile, and operational exposure</span></div>${badge('₹'+allocated+'L allocated')}</div><table class="table finance-table"><thead><tr><th>Active intervention</th><th>Allocated budget</th><th>Expected payback</th><th>Operational risk</th><th>Execution progress</th><th>Carbon impact</th></tr></thead><tbody>${work.map((i,n)=>`<tr><td><b>${i.name}</b><small>${i.facility}</small></td><td>₹${i.cost_lakh.toFixed(1)}L</td><td>${[1.8,2.4,2.1,4.6][n]} years</td><td>${badge(i.risk,i.risk!=='Low')}</td><td><div class="row-progress"><i style="width:${progress[n]}%"></i></div><small>${progress[n]}% complete</small></td><td class="good">−${i.co2_reduction_t} tCO₂e</td></tr>`).join('')}</tbody></table></section></div>`}
function hotspots(){return head('DIAGNOSIS','Focus effort where it matters','Rank operational drivers by absolute impact and move the strongest hotspot into an intervention workflow.',`<button class="btn primary" onclick="go('interventions')">Review top action →</button>`)+`<section class="panel"><div class="ph"><div><h3>Ranked hotspots</h3><span class="sub">Organisation → facility → resource</span></div></div><table class="table"><thead><tr><th>Rank</th><th>Facility / driver</th><th>Scope</th><th>Impact</th><th>Contribution</th><th>Trend</th></tr></thead><tbody>${data.hotspots.map(h=>`<tr><td>#${h.rank}</td><td><b>${h.resource}</b><small>${h.facility}</small></td><td>${badge(h.scope)}</td><td>${h.impact_t.toLocaleString()} tCO₂e</td><td>${h.contribution}%</td><td class="${h.trend<0?'good':''}">${h.trend>0?'+':''}${h.trend}%</td></tr>`).join('')}</tbody></table></section>`}
function interventions(){return head('ACTION CATALOGUE','Candidate interventions','Compare impact, cost, operational risk, and evidence readiness before committing capital.')+`<section class="panel"><table class="table"><thead><tr><th>Intervention</th><th>Facility</th><th>Predicted</th><th>CAPEX</th><th>Evidence</th><th>Status</th><th></th></tr></thead><tbody>${data.interventions.map(i=>`<tr><td><b>${i.name}</b><small>${i.category}</small></td><td>${i.facility}</td><td class="good">−${i.predicted}%</td><td>₹${i.cost_lakh}L</td><td>${i.evidence}/100</td><td>${badge(i.status,i.status==='Candidate')}</td><td>${i.id==='hvac'?`<button class="btn primary" onclick="go('pilots')">Design pilot</button>`:''}</td></tr>`).join('')}</tbody></table></section>`}
function pilots(){const c=data.contract,ready=c.status==='ready';return head(`DECISION CONTRACT · REVISION ${c.revision}`,c.intervention,c.facility,`${ready?`<button class="btn primary" onclick="approve()">Approve pilot</button>`:c.status==='approved'?`<button class="btn primary" onclick="startPilot()">Start pilot</button>`:`<button class="btn primary" onclick="replay()">Replay intervention</button>`}`)+`<div class="contract"><article class="panel doc"><div class="ph"><div><h3>Pre-commitment for measurable intervention</h3><span class="sub">PL-2026-004</span></div>${badge(c.status,c.status==='running')}</div><div class="section"><h4>01 · Hypothesis</h4><div class="field">${c.hypothesis}</div></div><div class="section"><h4>02 · Success metrics</h4><div class="grid"><div class="field c7"><small>Primary KPI</small><br><b>${c.primary_kpi}</b></div><div class="field c5"><small>Success threshold</small><br><b>≥ ${c.minimum_success_threshold}%</b></div></div><div class="tags">${c.secondary_kpis.map(x=>`<span class="tag">${x}</span>`).join('')}</div></div><div class="section"><h4>03 · Baseline and pilot</h4><p class="field"><b>Baseline</b> ${c.baseline}<br><br><b>Pilot</b> ${c.pilot}</p></div><div class="section"><h4>04 · Counterfactual</h4><div class="field"><b>${c.control}</b><br><small>Difference-in-Differences eligible · parallel trend p = 0.34</small></div></div><div class="section"><h4>05 · Guardrails</h4><div class="tags">${c.guardrails.map(x=>`<span class="tag">${x}</span>`).join('')}</div></div><div class="section"><h4>06 · Required evidence</h4><ul class="checks">${c.required_evidence.map(x=>`<li>✓ ${x}</li>`).join('')}</ul></div></article><aside class="panel sidecard"><h3>Pilot readiness</h3><div class="score">91<small>/100</small></div><div class="progress"><i style="width:91%"></i></div><p>${badge('Decision-grade')}</p><ul class="checks"><li>✓ Baseline complete</li><li>✓ Factor provenance</li><li>✓ Measurement plan</li><li>✓ Credible control</li></ul>${ready?`<button class="btn primary" onclick="approve()">Approve pilot</button>`:c.status==='approved'?`<button class="btn primary" onclick="startPilot()">Start pilot</button>`:`<button class="btn primary" onclick="replay()">Replay 28-day pilot</button>`}</aside></div>`}
function proof(){const p=data.proof,pts=p.series.map((x,i)=>`${i*100/(p.series.length-1)},${100-(x.actual-65)*2.5}`).join(' '),cf=p.series.map((x,i)=>x.counterfactual==null?'':`${i*100/(p.series.length-1)},${100-(x.counterfactual-65)*2.5}`).filter(Boolean).join(' ');return head('CAUSAL VERIFICATION · PL-2026-004','What changed—and would it have happened anyway?','Observed performance is compared with a production-normalised counterfactual using the pre-committed method.',`<button class="btn" onclick="go('rebound')">Check rebound →</button>`)+`<div class="proof-banner"><div><b>✓</b></div><div><small>EVIDENCE STATUS</small><h3>${p.status}</h3><p>Gate score 91/100 · Result clears the minimum 8% threshold</p></div></div><div class="metrics">${metric('Predicted effect','−14.0%','Pre-committed estimate')}${metric('Verified effect','−10.3%','95% CI −12.8 to −7.7%')}${metric('Prediction error','3.7 pp','Prediction was optimistic')}${metric('Absolute effect','−31.8 MWh','Against counterfactual')}</div><section class="panel"><div class="ph"><div><h3>Observed vs counterfactual trajectory</h3><span class="sub">Weekly kWh per 1,000 units</span></div>${badge('Medium–high confidence')}</div><div class="proof-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><polyline points="${cf}" fill="none" stroke="#7b8580" stroke-width=".7" stroke-dasharray="2 2"/><polyline points="${pts}" fill="none" stroke="#185b4c" stroke-width="1"/></svg></div><div class="legend"><span><i style="background:#185b4c"></i>Actual</span><span><i style="background:#7b8580"></i>Counterfactual</span></div></section>`}
function rebound(){const p=data.proof;return head('UNINTENDED CONSEQUENCES','Efficiency improved. Absolute benefit moved less.','ProofLoop checks the verified intervention across absolute, intensity, resource, scope, and timing dimensions.',`<button class="btn primary" onclick="go('memory')">Update decision memory →</button>`)+`<div class="alert"><b>△</b><div><small>DETECTED EVENT</small><h3>${data.rebound.type}</h3><p>${data.rebound.message}</p></div></div><div class="metrics">${metric('Energy intensity',`${p.intensity_change}%`,'Verified improvement')}${metric('Production',`+${p.production_change}%`,'Post-intervention growth')}${metric('Total electricity',`${p.absolute_change}%`,'Absolute effect')}${metric('Scope 2','−24.6 t','Net impact')}</div><section class="panel"><div class="ph"><div><h3>Consequence trace</h3><span class="sub">Verified downstream impact chain</span></div>${badge('Review before rollout',true)}</div><div class="flow"><div class="node dark">HVAC schedule<br><b>Intervention</b></div><span class="arrow">→</span><div class="node good">Intensity<br><b>−10.3%</b></div><span class="arrow">→</span><div class="node">Production<br><b>+8.1%</b></div><span class="arrow">→</span><div class="node warn">Absolute energy<br><b>−3.1%</b></div><span class="arrow">→</span><div class="node good">Scope 2<br><b>−24.6 t</b></div></div></section>`}
function memory(){return head('ORGANISATIONAL LEARNING','Make every intervention improve the next one','Compare forecasts with verified effects, calibrate future predictions, and test whether evidence should transfer.',`<button class="btn" onclick="go('evidence')">Trace evidence →</button>`)+`<div class="grid"><section class="panel c4"><span class="sub">PREDICTION RELIABILITY</span><div class="reliability">${data.calibration.factor}</div><p class="sub">Median verified / predicted ratio</p></section><section class="panel c8"><h3>What have we learned?</h3><p style="font-size:10px;line-height:1.7">HVAC forecasts have been optimistic. Apply the <b>0.84 reliability factor</b> until more verified pilots are available.<br><br>Production-normalised KPIs are essential: Chennai's efficiency gain was materially larger than its absolute electricity reduction.</p></section><section class="panel c12"><div class="ph"><div><h3>Prediction calibration ledger</h3><span class="sub">Predicted vs verified effect</span></div></div>${data.memory.map(m=>`<div class="memory-row"><b>${m.name}</b><span>Predicted ${m.predicted}%</span><span class="good">Verified ${m.verified}%</span><span>${badge(m.status,m.status!=='Verified')}</span></div>`).join('')}</section><section class="panel c12"><div class="ph"><div><h3>Transferability explorer</h3><span class="sub">Chennai source → Hosur target</span></div>${badge('EcoMind heuristic')}</div><div class="flow"><div class="node good">Chennai Plant<br><b>−10.3% verified</b></div><span class="arrow">→ <b>84%</b> →</span><div class="node warn">Hosur Plant<br><b>Limited pilot</b></div></div></section></div>`}
function evidence(){return head('AUDITABILITY','Every conclusion leaves a trail','Search the input source, formula, factor, assumptions, time, and result behind each major calculation.')+`<section class="panel"><table class="table"><thead><tr><th>Evidence</th><th>Source</th><th>Method</th><th>Recorded</th><th>Status</th></tr></thead><tbody>${data.evidence.map(e=>`<tr><td><b>${e.title}</b><small>${e.id}</small></td><td>${e.source}</td><td>${e.method}</td><td>${e.date}</td><td>${badge(e.status,e.status!=='Validated')}</td></tr>`).join('')}</tbody></table></section>`}
function dataCenter(){const q=data.data_quality||{overall:86,streams:[],anomalies:[]};const result=uploadResult?`<div class="import-summary"><div><b>${uploadResult.imported||0}</b><small>Imported</small></div><div><b>${uploadResult.warnings||0}</b><small>Warnings</small></div><div class="${uploadResult.rejected?'bad':''}"><b>${uploadResult.rejected||0}</b><small>Rejected</small></div><p>${uploadResult.message||'Validation complete. Preview and provenance have been recorded.'}</p></div>`:'';return head('DATA INGESTION & VALIDATION','Data Center','Ingest operational evidence, monitor quality by stream, and investigate anomalies before they influence decisions.',`<button class="btn" onclick="toggleAnomalies()">Anomaly log · ${q.anomalies.length}</button><button class="btn primary" onclick="document.getElementById('source-file').click()">Upload source</button>`)+`<div class="quality-grid">${q.streams.map(s=>`<article class="quality-card"><div class="quality-head"><span class="stream-icon ${s.id}"></span><div><b>${s.label}</b><small>${s.records.toLocaleString()} records · ${s.coverage} coverage</small></div><strong>${s.score}%</strong></div><div class="quality-track"><i style="width:${s.score}%"></i></div><p>${badge(s.status,s.score<85)}</p></article>`).join('')}</div><div class="grid"><section class="panel c8"><div class="ph"><div><h3>Source ingestion</h3><span class="sub">CSV validation is live · Excel and PDF sources enter the document-processing queue</span></div>${badge('Quality gate active')}</div><input id="source-file" type="file" accept=".csv,.xlsx,.xls,.pdf" hidden onchange="handleUpload(this.files[0])"><div class="upload-zone" onclick="document.getElementById('source-file').click()" ondragover="event.preventDefault()" ondrop="dropFile(event)"><div class="upload-icon">⇧</div><b>Drop CSV, Excel, or PDF evidence here</b><span>Up to 2 MB · filenames sanitized · provenance captured</span><button class="btn">Choose source</button></div>${result}</section><section class="panel c4"><div class="ph"><div><h3>Overall quality index</h3><span class="sub">Weighted validation metrics</span></div></div><div class="quality-gauge"><strong>${q.overall}%</strong><span>decision-ready</span></div><div class="quality-factor"><span>Completeness</span><b>91%</b></div><div class="quality-factor"><span>Source reliability</span><b>88%</b></div><div class="quality-factor"><span>Temporal coverage</span><b>94%</b></div><div class="quality-factor"><span>Factor provenance</span><b>76%</b></div></section><section class="panel c12"><div class="ph"><div><h3>Source registry</h3><span class="sub">Connected systems and latest validation outcome</span></div></div><table class="table"><thead><tr><th>Source</th><th>Stream</th><th>Facility</th><th>Coverage</th><th>Validation</th><th>Quality</th></tr></thead><tbody><tr><td><b>Schneider PM8000</b><small>Smart-meter API</small></td><td>Electricity</td><td>Chennai</td><td>Jan–Aug 2026</td><td>${badge('Validated')}</td><td class="good">98%</td></tr><tr><td><b>Fuel ledger export</b><small>ERP monthly CSV</small></td><td>Fuel</td><td>All facilities</td><td>Jan–Aug 2026</td><td>${badge('Validated')}</td><td class="good">94%</td></tr><tr><td><b>Municipal meters</b><small>Manual + API</small></td><td>Water</td><td>Chennai + Hosur</td><td>Feb–Aug 2026</td><td>${badge('Review',true)}</td><td>81%</td></tr><tr><td><b>Waste manifests</b><small>PDF evidence</small></td><td>Waste</td><td>Bengaluru</td><td>Apr–Aug 2026</td><td>${badge('Action needed',true)}</td><td>72%</td></tr></tbody></table></section></div>${drawerOpen?`<div class="drawer-scrim" onclick="toggleAnomalies()"></div><aside class="anomaly-drawer"><div class="drawer-title"><div><small>DATA QUALITY</small><h3>Anomaly log</h3></div><button onclick="toggleAnomalies()">×</button></div><p>Issues are ranked by their potential to distort calculations or block verification.</p>${q.anomalies.map(a=>`<article><div>${badge(a.severity,a.severity!=='Low')}<small>${a.time}</small></div><b>${a.stream}</b><p>${a.message}</p></article>`).join('')}<button class="btn primary" onclick="go('insights')">Generate remediation plan</button></aside>`:''}`}
function sustainability(){const total=data.overview.co2e_t;return head('EMISSIONS INTELLIGENCE','Sustainability deep dive','Inspect Scope 1–3 composition, factor provenance, facility intensity, and the operating activities behind organizational hotspots.',`<button class="btn" onclick="go('data-center')">Factor quality</button><button class="btn primary" onclick="go('scenario-lab')">Model reductions →</button>`)+`<div class="grid"><section class="panel c5"><div class="ph"><div><h3>Scope composition</h3><span class="sub">Reported tCO₂e</span></div></div><div class="scope-visual"><div class="scope-donut"><strong>${total.toLocaleString()}</strong><small>tCO₂e</small></div><div class="scope-legend"><div><i class="s1"></i><span>Scope 1 · Direct</span><b>${Math.round(total*.24).toLocaleString()} t</b></div><div><i class="s2"></i><span>Scope 2 · Energy</span><b>${Math.round(total*.58).toLocaleString()} t</b></div><div><i class="s3"></i><span>Scope 3 · Value chain</span><b>${Math.round(total*.18).toLocaleString()} t</b></div></div></div></section><section class="panel c7"><div class="ph"><div><h3>Hotspot contribution</h3><span class="sub">Absolute footprint vs production-normalised intensity</span></div>${badge('4 material drivers')}</div><div class="sustain-bars">${data.hotspots.map(h=>`<div><span><b>${h.resource}</b><small>${h.facility} · ${h.scope}</small></span><i><em style="width:${h.contribution*3}%"></em></i><strong>${h.impact_t.toLocaleString()} t</strong></div>`).join('')}</div></section><section class="panel c12"><div class="ph"><div><h3>Emission factor register</h3><span class="sub">Versioned factor sources behind current calculations</span></div>${badge('Illustrative demo factors',true)}</div><table class="table"><thead><tr><th>Category</th><th>Factor</th><th>Unit</th><th>Scope</th><th>Source</th><th>Vintage</th></tr></thead><tbody>${(data.factor_sources||[]).map(f=>`<tr><td><b>${f.category}</b></td><td>${f.factor}</td><td>${f.unit}</td><td>${badge(f.scope)}</td><td>${f.source}</td><td>${f.year}</td></tr>`).join('')}</tbody></table></section></div>`}
function scenarioLab(){const s=scenarioState,r=s.result;return head('WHAT-IF MODELING','Scenario Lab','Adjust operating assumptions and recalculate absolute emissions and carbon intensity against the preserved baseline.',`<button class="btn" onclick="resetScenario()">Reset baseline</button><button class="btn primary" onclick="runScenario()">Recalculate</button>`)+`<div class="scenario-layout"><section class="panel scenario-controls"><h3>Operating assumptions</h3><p class="sub">Changes are sent to the deterministic scenario endpoint.</p>${rangeControl('Energy consumption','energy',s.energy,-30,20,'%')}${rangeControl('Fuel consumption','fuel',s.fuel,-30,20,'%')}${rangeControl('Production volume','production',s.production,-15,30,'%')}<div class="scenario-note"><b>Method</b><p>Scope-weighted activity adjustment with production-normalised intensity recalculation.</p></div></section><section class="scenario-output"><div class="scenario-hero"><div><small>PROJECTED NET EMISSIONS</small><strong>${r?r.projected_co2e.toLocaleString():'6,428'} <em>tCO₂e</em></strong><p>${r?`${signed(r.absolute_change)}% absolute change · ${signed(r.intensity_change)}% intensity change`:'Move a control to calculate the scenario.'}</p></div><div class="scenario-delta ${r&&r.absolute_change<0?'down':''}">${r?signed(r.absolute_change)+'%':'—'}</div></div><div class="metrics four-metrics">${metric('Energy',r?`${r.energy_mwh.toLocaleString()} MWh`:'11,820 MWh',`${signed(s.energy)}% assumption`)}${metric('Fuel',r?`${r.fuel_kl.toLocaleString()} kL`:'842 kL',`${signed(s.fuel)}% assumption`)}${metric('Production index',r?r.production_index:'100',`${signed(s.production)}% assumption`)}${metric('Carbon intensity',r?`${signed(r.intensity_change)}%`:'—','Per production unit')}</div><section class="panel"><div class="ph"><div><h3>Scenario reconciliation</h3><span class="sub">How operating changes flow to the result</span></div></div><div class="flow"><div class="node dark">Baseline<br><b>6,428 tCO₂e</b></div><span class="arrow">→</span><div class="node">Energy<br><b>${signed(s.energy)}%</b></div><div class="node">Fuel<br><b>${signed(s.fuel)}%</b></div><div class="node">Production<br><b>${signed(s.production)}%</b></div><span class="arrow">→</span><div class="node good">Intensity<br><b>${r?signed(r.intensity_change)+'%':'Pending'}</b></div></div></section></section></div>`}
function interventionMarketplace(){const wanted=['solar','hvac','motors','ev'],labels={solar:'Renewable supply',hvac:'Operational control',motors:'Machine efficiency',ev:'Fleet transition'},symbols={solar:'☼',hvac:'❄',motors:'⚙',ev:'↯'};return head('INTERVENTION MARKETPLACE','Compare action pathways','Evaluate cost, carbon benefit, operational exposure, and evidence readiness before moving an action into optimization or a Decision Contract.',`<button class="btn" onclick="go('optimization')">Compare portfolio</button><button class="btn primary" onclick="go('decision-contracts')">Build contract →</button>`)+`<div class="market-grid">${wanted.map(id=>data.interventions.find(i=>i.id===id)).filter(Boolean).map(i=>`<article class="market-card"><div class="market-top"><span class="market-symbol">${symbols[i.id]}</span>${badge(i.status,i.status==='Hypothesis')}</div><small>${labels[i.id]}</small><h3>${i.name}</h3><p>${i.facility}</p><div class="market-impact"><div><span>Carbon impact</span><b>−${i.co2_reduction_t} t</b></div><div><span>Predicted</span><b>−${i.predicted}%</b></div></div><div class="market-meta"><span>CAPEX <b>₹${i.cost_lakh}L</b></span><span>Risk ${badge(i.risk,i.risk!=='Low')}</span><span>Evidence <b>${i.evidence}/100</b></span></div><button class="btn ${i.id==='hvac'?'primary':''}" onclick="go('${i.id==='hvac'?'decision-contracts':i.id==='motors'?'optimization':'scenario-lab'}')">${i.id==='hvac'?'Design pilot':'Model action'} →</button></article>`).join('')}</div><section class="panel"><div class="ph"><div><h3>Full intervention register</h3><span class="sub">Existing catalogue retained</span></div></div><table class="table"><thead><tr><th>Intervention</th><th>Facility</th><th>CAPEX</th><th>Predicted effect</th><th>Evidence</th><th>Status</th></tr></thead><tbody>${data.interventions.map(i=>`<tr><td><b>${i.name}</b><small>${i.category}</small></td><td>${i.facility}</td><td>₹${i.cost_lakh}L</td><td class="good">−${i.predicted}%</td><td>${i.evidence}/100</td><td>${badge(i.status,i.status==='Hypothesis')}</td></tr>`).join('')}</tbody></table></section>`}
function optimization(){const s=optimizationState,r=s.result;return head('MULTI-CONSTRAINT DECISIONING','Portfolio Optimization','Set capital, carbon, and operational constraints. The deterministic optimizer selects the highest-impact feasible combination.',`<button class="btn" onclick="resetOptimization()">Reset</button><button class="btn primary" onclick="runOptimization()">Calculate optimum</button>`)+`<div class="optimization-layout"><section class="panel scenario-controls"><h3>Portfolio constraints</h3>${rangeControl('Budget limit','budget',s.budget,10,100,'₹L',true)}${rangeControl('Target CO₂ drop','target',s.target,1,15,'%',true)}${rangeControl('Downtime limit','downtime',s.downtime,1,15,'days',true)}<div class="constraint-check"><span>Water increase</span>${badge('Not allowed')}</div><div class="constraint-check"><span>Production impact</span>${badge('≤ 1%')}</div><button class="btn primary" onclick="runOptimization()">Run optimization</button></section><section class="panel optimization-result"><div class="ph"><div><h3>Recommended portfolio</h3><span class="sub">Maximum verified-potential benefit within constraints</span></div>${r?badge(r.target_met?'All constraints met':'Target gap',!r.target_met):badge('Awaiting calculation')}</div>${r?`<div class="optimization-summary"><div><small>SELECTED ACTIONS</small><b>${r.selected.length}</b></div><div><small>TOTAL CAPEX</small><b>₹${r.total_cost_lakh}L</b></div><div><small>CARBON BENEFIT</small><b>−${r.impact_t} t</b></div><div><small>DOWNTIME</small><b>${r.downtime_days} days</b></div></div><div class="selected-actions">${r.selected.map((name,i)=>`<div><span>0${i+1}</span><b>${name}</b><em>✓ selected</em></div>`).join('')}</div><div class="constraint-result"><span>Budget <b>✓</b></span><span>Downtime <b>✓</b></span><span>CO₂ target <b class="${r.target_met?'good':'bad-text'}">${r.target_met?'✓':'Gap'}</b></span><span>Unused budget <b>₹${r.unused_budget_lakh}L</b></span></div>`:`<div class="empty"><b>No optimized portfolio yet</b><p>Set constraints and calculate the best feasible combination.</p></div>`}</section></div>`}
function decisionContracts(){const c=data.contract;return head(`PRE-IMPLEMENTATION CONTROL · REVISION ${c.revision}`,'Decision Contract Builder','Pre-commit the baseline, predicted saving, evaluation window, success threshold, and evidence requirements before implementation.',`${badge(c.status,c.status==='running')}<button class="btn primary" onclick="saveContract()">Generate contract</button>`)+`<div class="contract-builder"><form class="panel contract-form" onsubmit="event.preventDefault();saveContract()"><div class="ph"><div><h3>Formal intervention contract</h3><span class="sub">PL-2026-004 · ${c.facility}</span></div><div class="confidence"><strong>${data.gate.score}</strong><small>confidence</small></div></div><label><span>Hypothesis</span><textarea id="contract-hypothesis">${c.hypothesis}</textarea></label><div class="form-pair"><label><span>Primary KPI</span><input id="contract-kpi" value="${c.primary_kpi}"></label><label><span>Minimum success threshold</span><input id="contract-threshold" type="number" value="${c.minimum_success_threshold}"><em>% reduction</em></label></div><div class="form-pair"><label><span>Baseline evaluation window</span><input id="contract-baseline" value="${c.baseline}"></label><label><span>Target evaluation window</span><input id="contract-pilot" value="${c.pilot}"></label></div><div class="section"><h4>Guardrails</h4><div class="tags">${c.guardrails.map(x=>`<span class="tag">${x}</span>`).join('')}</div></div><div class="section"><h4>Evidence requirements</h4><ul class="checks">${c.required_evidence.map(x=>`<li>✓ ${x}</li>`).join('')}</ul></div><div class="form-actions"><button class="btn" type="button" onclick="go('interventions')">Back to marketplace</button><button class="btn primary" type="submit">Save Decision Contract</button></div></form><aside class="panel sidecard"><h3>Contract readiness</h3><div class="score">${data.gate.score}<small>/100</small></div><div class="progress"><i style="width:${data.gate.score}%"></i></div><p>${badge(data.gate.label)}</p><ul class="checks"><li>✓ 13-week baseline</li><li>✓ Versioned factor source</li><li>✓ Matched Hosur control</li><li>✓ Stop conditions defined</li></ul><p class="sub">Approver<br><b>${c.approver}</b></p>${c.status==='ready'?`<button class="btn primary" onclick="approve()">Approve pilot</button>`:c.status==='approved'?`<button class="btn primary" onclick="startPilot()">Start pilot</button>`:`<button class="btn primary" onclick="replay()">Replay completed pilot</button>`}</aside></div>`}
function verificationHub(){const p=data.proof,actual=p.series.map((x,i)=>`${i*100/(p.series.length-1)},${100-(x.actual-65)*2.5}`).join(' '),counter=p.series.map((x,i)=>x.counterfactual==null?'':`${i*100/(p.series.length-1)},${100-(x.counterfactual-65)*2.5}`).filter(Boolean).join(' ');return head('MEASUREMENT & VERIFICATION','Verification Hub','Compare the committed baseline, model prediction, and measured outcome—then diagnose whether production growth offset the absolute reduction.',`<button class="btn" onclick="go('decision-contracts')">View contract</button><button class="btn primary" onclick="go('decision-memory')">Store learning →</button>`)+`<div class="proof-banner"><div class="verify-icon">✓</div><div><small>EVIDENCE STATUS</small><h3>${p.status} · ${p.method}</h3><p>Evidence gate ${data.gate.score}/100 · 30 observed weeks · adjusted model R² ${p.diagnostics.r_squared}</p></div>${badge('Decision-grade')}</div><div class="metrics four-metrics">${metric('Baseline','91.9 kWh','Counterfactual post-period')}${metric('Predicted','−14.0%','Committed estimate')}${metric('Actual','−10.3%','Verified effect')}${metric('Prediction error','3.7 pp','Calibration input')}</div><div class="grid"><section class="panel c8"><div class="ph"><div><h3>Baseline vs predicted vs actual</h3><span class="sub">Weekly energy intensity · kWh per 1,000 units</span></div><div class="legend"><span><i style="background:#185b4c"></i>Actual</span><span><i style="background:#7b8580"></i>Counterfactual</span></div></div><div class="proof-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><polyline points="${counter}" fill="none" stroke="#7b8580" stroke-width=".7" stroke-dasharray="2 2"/><polyline points="${actual}" fill="none" stroke="#185b4c" stroke-width="1"/></svg></div></section><section class="panel c4 rebound-widget"><div class="ph"><div><h3>Rebound Effect Diagnostic</h3><span class="sub">Automated post-proof check</span></div>${badge('Partial offset',true)}</div><div class="rebound-core"><strong>7.2 <small>pp</small></strong><span>expected absolute saving absorbed by production growth</span></div><div class="diag-row"><span>Per-unit carbon intensity</span><b class="good">−10.3%</b></div><div class="diag-row"><span>Production volume</span><b>+8.1%</b></div><div class="diag-row"><span>Absolute electricity</span><b class="good">−3.1%</b></div><div class="diag-row"><span>Target absolute reduction</span><b>−8.0%</b></div><div class="rebound-explain">${data.rebound.message}</div></section><section class="panel c12"><div class="ph"><div><h3>Evidence and diagnostics</h3><span class="sub">Inputs behind the verified conclusion</span></div></div><div class="evidence-grid">${data.evidence.slice(0,3).map(e=>`<div><span>✓</span><b>${e.title}</b><small>${e.source} · ${e.method}</small></div>`).join('')}</div></section></div>`}
function insights(){return head('STRUCTURED ANALYST OUTPUT','Operational Insights','Evidence-bound recommendations generated from the current hotspot, quality, proof, rebound, and transferability records.',`<button class="btn" onclick="go('evidence')">Evidence register</button><button class="btn primary" onclick="go('verification')">Inspect verified result →</button>`)+`<div class="insight-layout"><section class="insight-feed">${(data.recommendations||[]).map((r,i)=>`<article class="panel insight-card"><div class="insight-priority">${r.priority}</div><div><small>RECOMMENDATION ${i+1}</small><h3>${r.title}</h3><p>${r.action}</p><div class="insight-impact"><span>Expected operational impact</span><b>${r.impact}</b></div><div class="tags">${r.evidence.map(e=>`<span class="tag">${e}</span>`).join('')}</div></div><aside><div class="confidence-ring">${r.confidence}<small>%</small></div><span>evidence confidence</span><button class="btn" onclick="go('${i===1?'data-center':i===2?'decision-memory':'verification'}')">Open evidence</button></aside></article>`).join('')}</section><aside class="panel insight-method"><h3>AI boundaries</h3><p>Recommendations summarize structured records. They do not calculate emissions, causal effects, evidence status, or financial values.</p><div class="method-check">✓ Sources disclosed</div><div class="method-check">✓ Structured evidence</div><div class="method-check">✓ Numeric fields locked</div><div class="method-check">✓ Generated 28 Aug 2026</div><hr><h3>Signals used</h3><div class="tag">Hotspot engine</div><div class="tag">M&V proof run</div><div class="tag">Rebound diagnostic</div><div class="tag">Data-quality gate</div></aside></div>`}
function simpleDashboard(){const o=data.overview,top=data.hotspots[0];return `<div class="simple-stats"><article><span>🌍</span><div><small>Total carbon pollution</small><strong>${o.co2e_t.toLocaleString()} tonnes</strong><p class="good">↓ ${Math.abs(o.co2e_change)}% compared with before</p></div></article><article><span>✓</span><div><small>Can we trust the data?</small><strong>${data.data_quality?.overall||o.data_readiness}% good</strong><p>Good enough for most decisions</p></div></article><article><span>🔧</span><div><small>Projects happening now</small><strong>${o.active_pilots} projects</strong><p>3 more projects already checked</p></div></article></div><section class="panel simple-problem"><div><span class="problem-icon">!</span><small>BIGGEST PROBLEM RIGHT NOW</small><h3>${top.resource}</h3><p>At ${top.facility}, this creates <b>${top.impact_t.toLocaleString()} tonnes</b> of carbon pollution. That is <b>${top.contribution}%</b> of the company total.</p></div><button class="btn primary" onclick="go('sustainability')">Understand this problem →</button></section><section class="simple-journey"><h3>How to use EcoMind</h3><p>Follow these five simple steps. You do not need technical knowledge.</p><div><button onclick="go('data-center')"><b>1</b><span>Upload your monthly data<small>Electricity, fuel, water, or waste</small></span></button><button onclick="go('sustainability')"><b>2</b><span>Find the biggest problem<small>See what creates the most pollution</small></span></button><button onclick="go('scenario-lab')"><b>3</b><span>Try a change<small>Test an idea before spending money</small></span></button><button onclick="go('optimization')"><b>4</b><span>Choose the best plan<small>Stay within your money and time limit</small></span></button><button onclick="go('verification')"><b>5</b><span>Check the result<small>See whether the project really worked</small></span></button></div></section>`}
function finalDashboard(){const o=data.overview,top=data.hotspots[0],direction=o.co2e_change<0?'lower':'higher',quality=data.data_quality.overall;return `<div class="simple-stats"><article><span>🌍</span><div><small>Total carbon pollution</small><strong>${o.co2e_t.toLocaleString()} tonnes</strong><p class="${o.co2e_change<0?'good':'bad'}">${signed(o.co2e_change)}% ${direction} than previous month</p></div></article><article><span>✓</span><div><small>Data quality</small><strong>${quality}%</strong><p>${quality>=90?'Strong enough for planning':'Review missing readings first'}</p></div></article><article><span>▦</span><div><small>Uploaded information</small><strong>${data.analysis.rows} rows</strong><p>${data.organization.period}</p></div></article></div><section class="panel simple-problem"><div><span class="problem-icon">!</span><small>BIGGEST SOURCE IN YOUR CSV</small><h3>${top.resource}</h3><p>At ${top.facility}, this creates <b>${top.impact_t.toLocaleString()} tonnes</b> of carbon pollution. That is <b>${top.contribution}%</b> of the uploaded total.</p></div><button class="btn primary" onclick="go('sustainability')">See all pollution sources →</button></section><section class="simple-journey"><h3>Your data journey</h3><p>Each page now uses the ${data.analysis.rows} unique rows from your uploaded CSV.</p><div><button onclick="go('data-center')"><b>1</b><span>Check uploaded data<small>${quality}% quality score</small></span></button><button onclick="go('sustainability')"><b>2</b><span>Find the biggest problem<small>${top.resource}</small></span></button><button onclick="go('scenario-lab')"><b>3</b><span>Try a change<small>Use your total as the starting point</small></span></button><button onclick="go('optimization')"><b>4</b><span>Choose the best plan<small>Calculated from your pollution sources</small></span></button><button onclick="go('verification')"><b>5</b><span>Check the result<small>Compare uploaded months</small></span></button></div></section>`}
function waitingPage(page){const label=pages.find(item=>item[0]===page)?.[1]||'This page';return `<section class="waiting-state"><div class="waiting-icon">↑</div><span>WAITING FOR YOUR DATA</span><h2>${label} will be calculated after upload</h2><p>Every value is currently zero. Upload the EcoMind CSV and the analysis engine will update all pages automatically.</p><div class="zero-preview"><div><small>Carbon pollution</small><b>0</b></div><div><small>Data quality</small><b>0%</b></div><div><small>Recommendations</small><b>0</b></div></div><button class="btn primary" onclick="go('data-center')">Upload CSV data →</button></section>`}
function simpleSustainability(){const total=data.overview.co2e_t,streams=data.stream_totals||{},scope=data.overview.scope||{};return `<div class="source-summary"><article><small>Direct fuel pollution</small><strong>${(scope['Scope 1']||0).toLocaleString()} t</strong><p>Fuel burned by the company</p></article><article><small>Electricity pollution</small><strong>${(scope['Scope 2']||0).toLocaleString()} t</strong><p>Electricity bought from the grid</p></article><article><small>Water and waste pollution</small><strong>${(scope['Scope 3']||0).toLocaleString()} t</strong><p>Other activities in the value chain</p></article></div><section class="panel source-breakdown"><div class="ph"><div><h3>Pollution by resource</h3><span class="sub">Calculated from your uploaded quantities and units</span></div><b>${total.toLocaleString()} t total</b></div>${['electricity','fuel','water','waste'].map(stream=>{const value=streams[stream]||0,share=total?value/total*100:0;return `<div class="source-row"><span><b>${STREAM_NAMES[stream]}</b><small>${share.toFixed(1)}% of total</small></span><i><em class="${stream}" style="width:${share}%"></em></i><strong>${value.toLocaleString()} t</strong></div>`}).join('')}</section><section class="panel simple-hotspots"><div class="ph"><div><h3>Where to act first</h3><span class="sub">Largest sources appear first</span></div></div>${data.hotspots.slice(0,5).map(h=>`<button onclick="go('interventions')"><b>${h.rank}</b><span>${h.resource}<small>${h.facility}</small></span><strong>${h.impact_t.toLocaleString()} t<small>${h.contribution}%</small></strong></button>`).join('')}</section>`}
const STREAM_NAMES={electricity:'Electricity',fuel:'Fuel',water:'Water',waste:'Waste'};
function simpleScenarioLab(){const s=scenarioState,r=s.result,o=data.overview;return `<div class="scenario-layout"><section class="panel scenario-controls"><h3>Change the assumptions</h3><p>Move a slider. EcoMind recalculates using your uploaded baseline.</p>${rangeControl('Electricity use','energy',s.energy,-30,20,'%')}${rangeControl('Fuel use','fuel',s.fuel,-30,20,'%')}${rangeControl('Production amount','production',s.production,-15,30,'%')}<div class="scenario-actions"><button class="btn" onclick="resetScenario()">Reset</button><button class="btn primary" onclick="runScenario()">Calculate result</button></div></section><section class="panel scenario-result-card"><span>ESTIMATED RESULT</span><h3>${r?r.projected_co2e.toLocaleString():o.co2e_t.toLocaleString()} <small>tonnes CO₂e</small></h3><p class="${r&&r.absolute_change<0?'good':''}">${r?`${Math.abs(r.absolute_change)}% ${r.absolute_change<0?'lower':'higher'} than your uploaded baseline`:'Change the sliders to calculate a result.'}</p><div class="result-compare"><div><small>Uploaded baseline</small><b>${o.co2e_t.toLocaleString()} t</b></div><div><small>Estimated result</small><b>${r?r.projected_co2e.toLocaleString():'—'} t</b></div><div><small>Per-product change</small><b>${r?signed(r.intensity_change)+'%':'—'}</b></div></div><small class="model-note">Estimate only. Use Check Results after implementation to measure the real outcome.</small></section></div>`}
function simpleVerification(){const p=data.proof,o=data.overview;return `<div class="verification-simple"><section class="panel result-verdict"><span>UPLOAD ANALYSIS</span><h3>${o.co2e_change<0?'Pollution went down':'Pollution did not go down'}</h3><strong class="${o.co2e_change<0?'good':''}">${signed(o.co2e_change)}%</strong><p>This compares the latest month with the previous month in your CSV.</p></section><section class="panel result-explain"><h3>Expected versus observed</h3><div><span>Typical HVAC estimate</span><b>−${p.predicted_effect}%</b></div><div><span>Change seen in uploaded periods</span><b class="good">−${p.verified_effect}%</b></div><div><span>Difference</span><b>${p.prediction_error} percentage points</b></div><p><b>Important:</b> this is a period comparison. It does not prove that one project caused the change.</p></section><section class="panel result-warning"><span>PRODUCTION CHECK</span><h3>More data is needed</h3><p>${data.rebound.message}</p><button class="btn" onclick="go('data-center')">Review uploaded data</button></section></div>`}
function simpleMemory(){const item=data.memory[0],factor=data.calibration.factor;return `<div class="memory-simple"><section class="panel"><span>WHAT THE SYSTEM LEARNED</span><h3>Your estimate needs adjustment</h3><p>The uploaded period improved by <b>${item?.verified||0}%</b>, compared with a typical estimate of <b>${item?.predicted||0}%</b>.</p><div class="learning-factor"><small>Future estimate multiplier</small><strong>${factor||0}</strong><p>A 10% estimate becomes ${Math.round(10*(factor||0)*10)/10}% until more verified projects are added.</p></div></section><section class="panel"><h3>Saved result</h3>${item?`<div class="saved-result"><b>${item.name}</b><span>Expected ${item.predicted}%</span><span>Observed ${item.verified}%</span><em>${item.status}</em></div>`:'<p>No result has been saved yet.</p>'}<p class="model-note">More completed projects will make future recommendations more accurate.</p></section></div>`}
function simpleDataCenter(){const q=data.data_quality||{overall:0,streams:[],anomalies:[]};const result=uploadResult?`<div class="upload-result ${uploadResult.rejected?'bad':''} ${uploadResult.loading?'loading':''}"><b>${uploadResult.loading?'Running EcoMind analysis…':uploadResult.rejected?'Please fix the file':'Analysis complete'}</b><p>${uploadResult.loading?'Checking rows, units, duplicates, and emission totals.':`${uploadResult.imported||0} rows accepted · ${uploadResult.warnings||0} duplicates ignored · ${uploadResult.rejected||0} rows rejected`}</p><span>${uploadResult.message||''}</span></div>`:'';return `<div class="csv-layout"><section class="panel csv-help"><span class="step-pill">Use a CSV file</span><h3>What should the file contain?</h3><p>Use <b>one row for each monthly reading</b>. The first row must have these five column names:</p><div class="csv-columns"><code>date</code><code>facility</code><code>stream</code><code>quantity</code><code>unit</code></div><div class="plain-example"><b>Example row</b><code>2026-08-01, Chennai Assembly Plant, electricity, 985400, kWh</code></div><ul class="plain-checks"><li><b>date</b> — reading date, written as YYYY-MM-DD</li><li><b>facility</b> — factory or office name</li><li><b>stream</b> — electricity, fuel, water, or waste</li><li><b>quantity</b> — number used during the month</li><li><b>unit</b> — kWh, litre, ML, or kg</li></ul><a class="btn download" href="/ecomind-20-row-emissions.csv" download>↓ Download 20-row CSV</a></section><section class="panel simple-upload"><input id="source-file" type="file" accept=".csv,text/csv" hidden onchange="handleUpload(this.files[0])"><div class="upload-zone" onclick="document.getElementById('source-file').click()" ondragover="event.preventDefault()" ondrop="dropFile(event)"><div class="upload-icon">↑</div><h3>Upload your CSV file</h3><p>Drag the file here, or choose it from your computer.</p><button class="btn primary">Choose CSV file</button><small>Maximum size: 2 MB</small></div>${result}</section></div><section class="panel quality-simple"><div class="quality-simple-head"><div><small>DATA CHECK</small><h3>How good is the current data?</h3><p>Green is good. Orange means some information is missing.</p></div><strong>${q.overall}%</strong></div><div class="quality-simple-grid">${q.streams.map(s=>`<div><span>${s.label}</span><b>${s.score}%</b><i><em style="width:${s.score}%"></em></i><small>${s.score>=90?'Good data':s.score>=80?'Needs a small check':'Needs improvement'}</small></div>`).join('')}</div><button class="btn" onclick="toggleAnomalies()">See ${q.anomalies.length} data problems</button></section>${drawerOpen?`<div class="drawer-scrim" onclick="toggleAnomalies()"></div><aside class="anomaly-drawer"><div class="drawer-title"><div><small>DATA PROBLEMS</small><h3>What needs fixing?</h3></div><button onclick="toggleAnomalies()">×</button></div>${q.anomalies.map(a=>`<article><b>${a.stream}</b><p>${a.message}</p></article>`).join('')}</aside>`:''}`}
function toggleDetails(){showDetails=!showDetails;render()}
const renders={dashboard:finalDashboard,overview,'data-center':simpleDataCenter,sustainability:simpleSustainability,'scenario-lab':simpleScenarioLab,interventions:interventionMarketplace,optimization,'decision-contracts':decisionContracts,verification:simpleVerification,'decision-memory':simpleMemory,insights,hotspots,pilots,proof,rebound,evidence};
function go(page){history.pushState({},'',`/${page}`);render()} function render(){const path=location.pathname.split('/').filter(Boolean)[0],raw=path||location.hash.slice(1)||'dashboard',aliases={overview:'dashboard',hotspots:'sustainability',pilots:'decision-contracts',proof:'verification',memory:'decision-memory'};const p=aliases[raw]||raw,renderer=renders[p]||finalDashboard,body=p!=='data-center'&&!data.has_data?waitingPage(p):renderer();document.getElementById('app').innerHTML=shell(p,body)}
async function post(path){const r=await fetch(API+path,{method:'POST'});if(!r.ok)throw Error((await r.json()).detail);await load();render()}
async function approve(){await post('/api/contracts/contract-hvac-chennai/approve')}async function startPilot(){await post('/api/contracts/contract-hvac-chennai/start')}async function replay(){await post('/api/pilots/replay');go('proof')}
function esc(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function signed(value){const n=Number(value);return `${n>0?'+':''}${n}`}
function rangeControl(label,key,value,min,max,suffix,isOptimization=false){return `<label class="range-control"><div><span>${label}</span><b id="${key}-value">${isOptimization&&key==='budget'?'₹':''}${value}${suffix==='%'?'%':suffix==='days'?' days':''}</b></div><input type="range" min="${min}" max="${max}" value="${value}" oninput="${isOptimization?'updateOptimization':'updateScenario'}('${key}',this.value)"><small>${min}${suffix==='%'?'%':''}</small><small>${max}${suffix==='%'?'%':''}</small></label>`}
function toggleAnomalies(){drawerOpen=!drawerOpen;render()}
function dropFile(event){event.preventDefault();const file=event.dataTransfer.files[0];if(file)handleUpload(file)}
async function handleUpload(file){if(!file)return;uploadResult={loading:true,message:`Analysing ${esc(file.name)}…`};render();const ext=file.name.split('.').pop().toLowerCase();if(ext!=='csv'){uploadResult={rejected:1,imported:0,message:'Please upload a CSV file using the EcoMind template.'};render();return}const response=await fetch(API+'/api/imports/validate',{method:'POST',headers:{'Content-Type':'text/plain'},body:await file.text()});uploadResult=await response.json();if(response.ok){await load();uploadResult.message=`${esc(file.name)} analysed successfully. All pages now use these ${uploadResult.imported} rows.`;render();setTimeout(()=>go('dashboard'),900);return}render()}
async function clearData(){if(!confirm('Clear the uploaded CSV and return every value to zero?'))return;await fetch(API+'/api/demo/reset',{method:'POST'});uploadResult=null;scenarioState={energy:-8,fuel:-4,production:6,result:null};optimizationState={budget:45,target:5,downtime:7,result:null};await load();go('dashboard')}
function updateScenario(key,value){scenarioState[key]=Number(value);runScenario()}
async function runScenario(){const response=await fetch(API+'/api/scenarios/simulate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({energy_adjustment:scenarioState.energy,fuel_adjustment:scenarioState.fuel,production_adjustment:scenarioState.production})});scenarioState.result=await response.json();render()}
function resetScenario(){scenarioState={energy:0,fuel:0,production:0,result:null};runScenario()}
function updateOptimization(key,value){optimizationState[key]=Number(value);render()}
async function runOptimization(){const response=await fetch(API+'/api/portfolio/optimize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({budget_lakh:optimizationState.budget,target_reduction:optimizationState.target,max_downtime:optimizationState.downtime,selected_ids:[]})});optimizationState.result=await response.json();render()}
function resetOptimization(){optimizationState={budget:45,target:5,downtime:7,result:null};render()}
async function saveContract(){const payload={hypothesis:document.getElementById('contract-hypothesis')?.value||data.contract.hypothesis,primary_kpi:document.getElementById('contract-kpi')?.value||data.contract.primary_kpi,minimum_success_threshold:Number(document.getElementById('contract-threshold')?.value||data.contract.minimum_success_threshold),baseline:document.getElementById('contract-baseline')?.value||data.contract.baseline,pilot:document.getElementById('contract-pilot')?.value||data.contract.pilot};const response=await fetch(API+'/api/contracts/contract-hvac-chennai/draft',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw Error('Contract could not be saved');await load();render()}
async function load(){const r=await fetch(API+'/api/demo',{cache:'no-store'});if(!r.ok)throw Error('Data service is unavailable');data=await r.json()} window.addEventListener('popstate',render);window.addEventListener('hashchange',render);load().then(render).catch(e=>document.getElementById('app').innerHTML=`<div class="boot">API unavailable: ${e.message}</div>`);
